query SensorAssignments($pageNumber: Int!, $pageSize: Int!) {
  sensorAssignments(page: { number: $pageNumber, size: $pageSize }) {
    data { id sensorId buildingId floorId spaceId }
    count
    total
    pageNumber
    pageSize
  }
}

query GetBuildings {
  buildings(page: { number: 1, size: 100 }, filters: { ids: ["471189ad7dc1d217d546f3ab6e92172b"], name: "The Discovery Centre" }) {
    data {
      id
      name
      city
      state
      country
      latitude
      longitude
      timezone
      reportsOnBookings
      reportsOnUtilization
      floors { name id }
    }
    count
    total
    pageNumber
    pageSize
  }
}

