query AverageUtilizationByBuildingAndDay {
  utilizationKpi(
    dateRange: { start: "2026-07-19T00:00:00Z", end: "2026-07-19T23:59:59Z" }
    page: { number: 1, size: 100 }
    groupBy: [Building, DayOfWeek]
    filters: {
      building: { ids: ["471189ad7dc1d217d546f3ab6e92172b"], name: "The Discovery Centre" }
      date: { daysOfWeek: [Sunday] }
      timeSlot: { hours: [0] }
    }
  ) {
    data { buildingId dayOfWeek sumOfOccupancy sumOfCapacity averageUtilization }
    count
    pageNumber
    pageSize
  }
}

query UtilizationKpiByBuilding($pageNumber: Int!, $pageSize: Int!, $dateRange: DateRange!, $groupBy: [UtilizationGrouping]!, $filters: UtilizationFilters) {
  utilizationKpi(
    dateRange: $dateRange
    page: { number: $pageNumber, size: $pageSize }
    groupBy: $groupBy
    filters: $filters
  ) {
    data {
      sumOfOccupancy
      sumOfCapacity
      averageUtilization
      buildingId
    }
    count
    total
    pageNumber
    pageSize
  }
}

query Utilizations {
  utilizations(
    dateRange: { start: "2026-07-19T00:00:00Z", end: "2026-07-19T23:59:59Z" }
    page: { number: 1, size: 100 }
    filters: { building: { ids: ["471189ad7dc1d217d546f3ab6e92172b"], name: "The Discovery Centre" }, floor: { ids: ["01143f825db004b13655ec988ceaf814"], name: "Floor M0" }, date: { daysOfWeek: [Sunday] }, timeSlot: { hours: [0] }, source: ["VS"] }
  ) {
    data {
      id
      buildingId
      floorId
      spaceId
      sensorAssignmentId
      date
      timeSlot
      occupancy
      capacity
      source
      userDefinedField1Id
      userDefinedField2Id
      userDefinedField3Id
    }
    count
    total
    pageNumber
    pageSize
  }
}

query BuildingsFilteredByName {
