}

query EnvironmentalPirTemperature {
  environmentalPIR(
    dateRange: { start: "2026-07-19T00:00:00Z", end: "2026-07-19T23:59:59Z" }
    page: { number: 1, size: 100 }
    filters: { building: { ids: ["5d307fe6f0078e0943f2175a8b1347fb"], name: "AMB" }, floor: { ids: ["91a9c19eeef7d0ace6894ea2af231952"], name: "Floor 2" }, sensor: { ids: ["8408d7e493b13db4ffc1748893ff00bd"] }, date: { daysOfWeek: [Sunday] }, timeSlot: { hours: [0] }, readingType: { name: "temp" } }
  ) {
    data {
      id
      buildingId
      floorId
      spaceId
      sensorAssignmentId
      date
      timeSlot
      value
      readingType
      unit
    }
    count
    total
    pageNumber
    pageSize
  }
}

query GetRecords($first: Int!, $after: String) {
  records(first: $first, after: $after) {
    edges {
      node {
        id
        name
        status
        createdAt
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

